def _retarget_inline_closing_line(text, replacement):
    """The shared RESPONSE_GENERATION_PROMPT ends with an arrest/FIR-
    flavoured "...upload the FIR or arrest memo here" line. These domains
    have no document-upload step in the chat-only app, so swap a trailing
    "upload ... here" line for a domain-appropriate one."""
    lines = (text or "").rstrip().split("\n")
    for i in range(len(lines) - 1, -1, -1):
        stripped = lines[i].strip()
        if not stripped:
            continue
        low = stripped.lower()
        if "upload" in low and ("here" in low or "full check" in low):
            lines[i] = replacement
        break
    return "\n".join(lines)


def _answer_inline_domain(question, domain):
    """Produce a full grounded answer for a 'covered_elsewhere_in_tool'
    domain (cheque_bounce / freeze) from the shared corpus's own case law
    (admitted via find_relevant_sections(domain=...)) plus that domain's
    curated doctrine anchors.

    Returns an answer_question-shaped dict on success, or None to let the
    caller fall back to the normal covered_elsewhere_in_tool redirect
    (retrieval down AND no anchor fired -- nothing honest to say).

    situation_detected is forced False: the recourse_app upload path feeds
    documents to the arrest analyzer, which has nothing to do with a
    cheque notice or a freeze letter, so no upload prompt should follow.

    Matching runs on the CURRENT message only (see
    _extract_current_message's docstring), with a fallback to the full,
    history-included `question` only if that narrow search finds
    nothing -- same fix, same reason, as the main answer_question path."""
    cfg = _INLINE_DOMAIN_CONFIG[domain]
    mod_name, fn_name = cfg["override_import"]
    override_fn = getattr(__import__(mod_name), fn_name)

    current_message = _extract_current_message(question)
    overrides = override_fn(current_message)
    result = _find_relevant_sections_for_turn(current_message, question, domain=domain)
    state = result.get("state")

    sem_judgments = result.get("judgment_matches", []) if state in ("single_match", "conflicting_matches") else []
    sem_statutes = result.get("matches", []) if state in ("single_match", "conflicting_matches") else []

    if not (overrides or sem_judgments):
        return None

    # The PROMPT gets everything: curated anchors PLUS the semantic hits
    # (extra factual context helps the model reason).
    prompt_matches = sem_statutes + sem_judgments + overrides
    prompt_matches = _inject_definitional_companions(prompt_matches)
    retrieved_text = format_retrieved_text_for_prompt(prompt_matches)
    response_text = generate_grounded_response(question, retrieved_text, matches=prompt_matches)
    if not response_text:
        return None

    response_text = _retarget_inline_closing_line(response_text, cfg["closing_line"])

    # The DISPLAY ("Read the source") shows only the curated, verified,
    # on-point anchor paragraphs -- never the semantic hits, which for a
    # narrative story pull in an unrelated case's background facts. A
    # statute the answer actually cites is still worth showing.
    display_matches = list(overrides) + [
        m for m in sem_statutes if m.get("section_number") and not m.get("case_name")
    ]

    result = {
        "state": "single_match",
        "matches": display_matches,
        "response_text": response_text,
        "situation_detected": False,
        "redirect_domain": domain,
    }

    vaquill_topic = cfg.get("vaquill_topic")
    if vaquill_topic:
        result["unverified_related_judgments"] = _fetch_unverified_related_judgments(
            question, vaquill_topic, exclude_case_names={m.get("case_name") for m in display_matches if m.get("case_name")}
        )

    return result


def _fetch_unverified_related_judgments(question: str, topic: str, exclude_case_names: set, top_k: int = 3) -> list:
    """The WIDER, honestly UNVERIFIED judgment pool -- see
    vaquill_search.py's module docstring and memory/vaquill-search-pool.md
    for the full design. NEVER folded into a grounded answer's own
    matches/response_text -- this is a separate list a caller (the
    website / WhatsApp formatter) renders under its own clearly-labelled
    "read carefully, not independently verified" heading, never
    presented with the same confidence as the curated anchors above.

    Excludes any case already cited as a curated anchor (no point
    telling someone to 'go read carefully' something already fully
    quoted and verified above). Swallows any failure (missing/corrupt
    local vaquill_search.db, e.g. on a fresh deploy that hasn't had it
    built yet) and returns [] rather than ever breaking the trusted
    answer this is attached to."""
    try:
        import vaquill_search
        results = vaquill_search.search(question, topic=topic, top_k=top_k + len(exclude_case_names))
    except Exception as exc:  # pragma: no cover - defensive
        logger.warning("_fetch_unverified_related_judgments: vaquill_search failed: %s", exc)
        return []

    filtered = [r for r in results if r.get("case_name") not in exclude_case_names]
    return filtered[:top_k]


# CONFIRMED REAL BUG (2026-09-27), found by re-checking wiring before adding a third pilot topic:
# pilot_tier_search.search_pilot_tier's `topic` parameter has existed since 2026-09-26 (built
# specifically to stop one topic's cases surfacing for an unrelated topic's question -- see
# memory/pilot-tier-judgment-search.md and the NDPS cross-topic-leakage incident that motivated
# it), fully implemented and tested in pilot_tier_search.py itself -- but the ONLY real (non-test)
# caller, _fetch_pilot_related_judgments below, never actually passed it. Every question has been
# searching the WHOLE pilot pool regardless of topic since the day the second topic
# (anticipatory_bail) was added, silently defeating the exact protection the parameter exists for.
#
# Fix: infer the topic from statute sections ALREADY found in `matches` (a signal that's free,
# deterministic, and confirmed by real testing -- BNS 115/117/122, the "Of Hurt" chapter, fire
# reliably and ONLY for genuine hurt/assault fact patterns; BNSS 482 fires reliably and ONLY for
# genuine anticipatory-bail questions; an unrelated theft question citing BNS 134/304 or a
# default-bail question citing BNSS 479/480 correctly triggers neither). Deliberately conservative:
# only narrows the search when exactly one topic's signal is present. Anything ambiguous (both
# signals) or absent (neither signal, e.g. a topic pilot_chunks has no case for yet) falls back to
# topic=None -- the exact old behaviour, searching everything -- so this can only ever REDUCE
# false-positive cross-topic leakage, never risk hiding a genuinely relevant pilot case behind an
# overconfident topic guess.
#
# EXTENDED 2026-09-27 for the third topic, cheating_civil_dispute (Hridaya Rangan Pd. Verma):
# confirmed empirically that "does non-payment of a loan count as cheating" reliably produces BNS
# 318 (cheating) and a breach-of-trust question reliably produces BNS 316 -- and neither fires for
# a hurt or bail question. Generalised to a dict so a future topic is one line, not a rewrite. Also
# fixed a real gap found while doing this: BNS 318 came back as "318(4)" (a sub-clause), which a
# bare string-equality check against "318" would have silently missed -- section numbers are now
# compared on their base number only (before any "(").
_PILOT_TOPIC_SECTION_SIGNALS = {
    "hurt_assault": {("BNS", str(n)) for n in range(114, 126)},
    "anticipatory_bail": {("BNSS", "482")},
    "cheating_civil_dispute": {("BNS", "318"), ("BNS", "316")},
}


def _base_section_number(section) -> str:
    """'318(4)' -> '318'; '122' unchanged. None/'' pass through unchanged -- never raises."""
    if not section:
        return section
    return section.split("(")[0].strip()


# CONFIRMED REAL BUG (2026-09-28, live WhatsApp test, "When can a court issue a non-bailable warrant?"): the
# section signal alone is not enough. Semantic retrieval returned BNSS 482 as one of several side matches for a
# WARRANT question, the inference above read it as "this is an anticipatory-bail question", and the pilot search was
# narrowed to the 3 anticipatory-bail cases (best score 0.454, under the 0.50 bar) -- so Inder Mohan Goswami, the
# case that actually answers the question (score 0.596 unfiltered), was hidden. The comment above claiming BNSS 482
# fires "ONLY for genuine anticipatory-bail questions" was wrong: it is a similarity match, so it also arrives with
# arrest/warrant questions.
#
# Fix: a topic is inferred only when BOTH agree -- a statute signal in the matches AND the question's own words
# carry that topic's cue. Anything else falls back to topic=None (search everything, the safe old default), so this
# can only make the inference MORE conservative. Cues are deliberately broad within their topic: missing one costs
# only an unfiltered search, whereas a wrong narrowing hides a relevant case. Note "482" is NOT an anticipatory-bail
# cue: under the old CrPC, s.482 is the High Court's power to QUASH (the Goswami case itself); it is BNSS 482 that
# is anticipatory bail, and a user quoting "482" usually means quashing.
_PILOT_TOPIC_QUESTION_CUES = {
    "hurt_assault": re.compile(
        r"\b(hit|hits|beat|beaten|beating|assault\w*|injur\w*|hurt|attack\w*|slap\w*|punch\w*|stab\w*|wound\w*|"
        r"fight|fought|blow|struck|thrash\w*|broke|broken|fracture\w*|bleed\w*|bled|grievous|weapon|stick|rod|knife|lathi)\b",
        re.IGNORECASE),
    "anticipatory_bail": re.compile(
        r"anticipatory|pre[- ]?arrest|advance bail|protection from arrest|\b438\b|"
        r"before (?:i am |i get |being |he is |she is |they |the police |police )?(?:arrest|arrested)|"
        r"(?:apprehend\w*|fear\w*|afraid|scared|worried)\s+(?:of\s+|that\s+)?(?:\w+\s+){0,3}?arrest",
        re.IGNORECASE),
    "cheating_civil_dispute": re.compile(
        r"cheat\w*|fraud\w*|deceiv\w*|dishonest\w*|\b420\b|\b318\b|breach of trust|misappropriat\w*|\bloan\b|"
        r"repay\w*|\bdefault\w*|forg\w*|\b467\b|civil (?:dispute|matter|suit|case)|sale deed|land (?:dispute|deal)",
        re.IGNORECASE),
}


def _infer_pilot_topic(matches: list, question: str = None) -> str:
    """Returns a pilot topic name only when EXACTLY ONE topic's signal is present across every
    statute match -- otherwise None (search the whole pilot pool, the safe default, unchanged
    from before this function existed). Never raises: an unexpected match shape is just skipped.

    `question` (ADDED 2026-09-28, see the CONFIRMED REAL BUG comment above): when given, a topic's
    section signal only counts if the question's own words also carry that topic's cue
    (_PILOT_TOPIC_QUESTION_CUES). When omitted (None) behaviour is the old signal-only inference, so
    a caller that has not been updated is unchanged."""
    signalled = set()
    for m in matches:
        if m.get("type") != "statute":
            continue
        key = (m.get("act"), _base_section_number(m.get("section_number")))
        for topic, signals in _PILOT_TOPIC_SECTION_SIGNALS.items():
            if key in signals:
                signalled.add(topic)
    if question is not None:
        signalled = {t for t in signalled
                     if (t not in _PILOT_TOPIC_QUESTION_CUES or _PILOT_TOPIC_QUESTION_CUES[t].search(question))}
    return signalled.pop() if len(signalled) == 1 else None


def _fetch_pilot_related_judgments(question: str, exclude_case_names: set, matches: list = None, top_k: int = 3) -> list:
    """The WIDER, hand-verified-but-not-fully-reviewed judgment pool (pilot_tier_search.py --
    2026-09-23 pilot, hurt/assault domain, 9 cases). Same shape and same caller contract as
    _fetch_unverified_related_judgments above -- merged into the SAME 'unverified_related_judgments'
    list both renderers already display, tagged source='pilot_wider_tier' so it's distinguishable
    from the vaquill pool in code, though shown under the same honest 'read carefully' heading (this
    pool's cases had their identity confirmed -- real names/dates checked against the real file --
    but not the full legal-content review the 46 curated cases get, so the same caution applies).

    `matches`, ADDED 2026-09-27: the caller's already-computed statute/judgment matches, used only
    to infer a topic filter via _infer_pilot_topic (see that function's docstring for why and how).
    Optional and defaults to None so any caller that hasn't been updated keeps the old, unfiltered
    behaviour rather than erroring.

    The 'ik_search_url' field is reused to carry this pool's REAL, human-verified Supreme-Court-of-
    India link (not an Indian Kanoon search page) -- deliberately reusing the existing field rather
    than adding a new one, so both renderers work with zero changes. paragraph_number is carried
    through only when pilot_tier_search itself found a genuine one (never invented here).

    Same fail-open contract as the vaquill fetch: any failure (missing pilot_chunks/, missing
    embeddings, import error) is swallowed and returns [] rather than ever risking the real answer
    this is attached to."""
    topic = _infer_pilot_topic(matches, question) if matches else None
    try:
        import pilot_tier_search
        results = pilot_tier_search.search_pilot_tier(question, topic=topic)
    except Exception as exc:  # pragma: no cover - defensive, same as the vaquill fetch above
        logger.warning("_fetch_pilot_related_judgments: pilot_tier_search failed: %s", exc)
        return []

    out = []
    for r in results:
        if r.get("case_name") in exclude_case_names:
            continue
        out.append({
            "source": "pilot_wider_tier",
            "case_name": r["case_name"],
            "ik_search_url": r["source_url"],
            "paragraph_number": r.get("paragraph_number") if r.get("chunk_method") == "paragraph_number" else None,
            # ADDED 2026-09-24: the UI-list renderers only ever read the fields above, but
            # generate_grounded_response now also needs the raw chunk text (and citation, for
            # display alongside a descriptive mention) to let the model reference this case in its
            # prose -- see _format_pilot_context_for_prompt. Purely additive; existing callers that
            # only read the fields above are unaffected.
            "citation": r.get("citation"),
            "text": r.get("text"),
        })
    return out[:top_k]


def _answer_single_match(question, matches):
    """Shared by every branch below that produces a 'single_match' result
    (the main path and both statute-override fallbacks) -- previously each
    duplicated the same retrieve/generate/situation_detected block.

    ADDED 2026-09-14 (answer-reuse cache, safe-by-design version of an
    idea deferred in memory/live-judgment-retrieval-plan.md): before
    paying for a fresh Sonnet call, checks answer_cache.get_cached(matches)
    -- a cache entry only exists at all when a PERSON has already reviewed
    and explicitly approved a past answer that used this EXACT set of
    matched sources (see answer_cache.py's module docstring for why
    matching on the tool's own deterministic sources, not the question's
    wording, keeps this safe). A cache miss behaves exactly as before:
    generate fresh, and record it as a candidate a person can later
    choose to approve. Cached or fresh, the answer itself is identical in
    shape -- callers cannot tell the difference except via 'from_cache'."""
    from answer_cache import get_cached, record_candidate

    use_cache = answer_style.uses_cache()      # the approved cache holds v1 wording written for laypeople: read and written only under v1 (v2, v3 and the lawyer note always generate fresh)
    try:                                       # a question that gets verbatim excerpts (ANCHORS=on) is generated fresh too: a cached answer was written without them
        import excerpt_anchors
        use_cache = use_cache and not excerpt_anchors.applies(question)
    except Exception:  # pragma: no cover
        pass
    cached = get_cached(matches) if use_cache else None
    if cached is not None:
        return {
            "state": "single_match",
            "matches": matches,
            "response_text": cached["response_text"],
            "situation_detected": cached["situation_detected"],
            "from_cache": True,
            "unverified_related_judgments": _fetch_pilot_related_judgments(
                question, exclude_case_names={m.get("case_name") for m in matches if m.get("case_name")}, matches=matches
            ),
        }

    # Runs AFTER the cache check, deliberately: the cache identity
    # (batch 6) stays exactly what it was based on the real retrieval,
    # unaffected by this purely-additive definitional material -- only a
    # FRESH generation gets the richer context.
    matches = _inject_definitional_companions(matches)
    retrieved_text = format_retrieved_text_for_prompt(matches)
    # Fetched ONCE, before generation (2026-09-24, at the user's explicit request): reused both to
    # let generate_grounded_response describe one of these in its prose (pilot_matches=) and to
    # populate the UI's separate "Other real court cases" list below -- a cached answer above never
    # sees this, since its response_text was already generated before this feature existed.
    pilot_matches = _fetch_pilot_related_judgments(
        question, exclude_case_names={m.get("case_name") for m in matches if m.get("case_name")}, matches=matches
    )
    response_text = generate_grounded_response(question, retrieved_text, matches=matches, pilot_matches=pilot_matches)
    situation_detected = _looks_like_situation(response_text)
    if use_cache:
        record_candidate(matches, question, response_text, situation_detected)
    return {
        "state": "single_match",
        "matches": matches,
        "response_text": response_text,
        "situation_detected": situation_detected,
        "from_cache": False,
        "unverified_related_judgments": pilot_matches,
    }


def _answer_question_core(question, inline_domains=frozenset()):
    """Main body of the chat entry point (call answer_question(), which wraps this). Returns a dict describing
    the outcome, always including a 'state' field so the UI layer can
    render each case distinctly and honestly, per this project's
    established "surface uncertainty, don't silently guess" principle
    throughout every other retrieval layer built this session.

        Possible states:
      'unrelated'          -- not a legal question, redirected politely
      'covered_elsewhere_in_tool' -- about bank freezing or cheque bounce,
                               which this chat feature's corpus doesn't
                               cover yet, but the wider tool genuinely
                               handles via document upload -- redirected
                               there, not told "not covered"
      'adjacent_uncovered'  -- real legal question, but outside what this
                               tool covers anywhere (BNS/BNSS chat scope
                               or the document-upload domains). With
                               SCOPE_GATE=open (2026-10-16) such a question
                               goes through the in_scope pipeline instead
                               and never reaches this state.
      'classifier_unavailable' -- couldn't even classify the question
      'no_match'           -- in scope, but nothing in the corpus cleared
                               the similarity threshold, AND no curated
                               statute override matched either
      'single_match'       -- one coherent, agreeing set of matches
      'conflicting_matches' -- multiple matches that disagree on a key
                               legal attribute (e.g. cognizability) --
                               never silently picks one
      'retrieval_unavailable' -- embeddings aren't set up (no API key,
                               no embeddings file, etc.)

    FIXED 2026-08-28: the conflicting_matches branch was previously
    nested INSIDE the no_match check's if-block (an indentation bug),
    making it unreachable -- since no_match returns immediately on its
    own condition, the nested conflicting_matches check could only ever
    fire if result["state"] was simultaneously "no_match" AND
    "conflicting_matches", which never happens. Real consequence: a
    genuine conflicting-matches result was silently falling through to
    the single_match handling below, mislabeling a conflict as a clean
    match. Fixed by making conflicting_matches a proper sibling
    elif, checked before the single_match fallthrough.

    ADDED 2026-08-28: a curated statute doctrine override check
    (statute_doctrine_map.py), covering known gaps where semantic
    search under-retrieves a specific high-stakes statute section
    (currently: BNSS 43(5), night-arrest-of-women safeguard, which
    scores ~0.343 against real "arrested at night" queries --
    indistinguishable from the confirmed-irrelevant ceiling ~0.339,
    per this project's own Aug 27 calibration data). This check runs
    BEFORE the normal semantic-search state handling, so it applies
    regardless of what score semantic search assigns -- it's a
    deliberate bypass for specific, known, verified gaps, not a
    replacement for semantic search generally. See
    statute_doctrine_map.py's module docstring for full reasoning and
    scope limits.
    """
    from statute_doctrine_map import get_statute_doctrine_override
    from itact_section_status import get_itact_status_override

    # classify_scope reads the FULL question (history included where
    # WhatsApp folds it in) -- a Haiku judgment call genuinely benefits
    # from earlier context for a short follow-up, and is not vulnerable
    # to the SAME failure as the deterministic matchers below (a JSON
    # category choice isn't "diluted" by extra text the way a similarity
    # score or a keyword scan is). Everything from here on that decides
    # WHAT THE CURRENT MESSAGE IS ABOUT uses current_message instead --
    # see _extract_current_message's docstring for the confirmed real
    # failure this avoids.
    category, reasoning, redirect_domain = classify_scope(question)
    current_message = _extract_current_message(question)
    _progress("scope", category=category or "unavailable")

    if category is None:
        return {"state": "classifier_unavailable"}

    if category == "unrelated":
        return {"state": "unrelated"}

    # Deterministic freeze nudge: a bank-account-freeze narrative that
    # also mentions a police investigation / "no FIR" reads as arrest-
    # flavoured, and the LLM classifier lands on in_scope (or cheque)
    # a real fraction of the time -- confirmed 2026-09-08. When the
    # message unmistakably describes the person's OWN bank account being
    # frozen/lien-marked and NOT the person being arrested, force the
    # freeze route so the freeze case law is what answers it. Same
    # "known, verified gap" spirit as the statute/offence anchors below.
    if _looks_like_bank_account_freeze(current_message) and category in (
        "in_scope", "adjacent_uncovered", "covered_elsewhere_in_tool",
    ):
        category, redirect_domain = "covered_elsewhere_in_tool", "freeze"

    # SCOPE_GATE=open (2026-10-16): the topic bar is lifted. A question the classifier called 'adjacent_uncovered' goes through the in_scope pipeline below; 'unrelated' (not a legal question) and the
    # inline domains are untouched. See the block above answer_question for what this does and does not promise.
    if category == "adjacent_uncovered" and _scope_gate_open():
        _open_topic_start(question, reasoning)
        category = "in_scope"

    if category == "covered_elsewhere_in_tool":
        # A caller with NO document-upload handoff of its own (the
        # chat-only recourse_app) can ask this function to answer a
        # cheque-bounce or bank-freeze question INLINE instead of dead-
        # ending it: the shared corpus holds the Section 138 case law
        # (Rangappa, Bir Singh, Prakash Chimanlal Sheth, Damodar S.
        # Prabhu, Kaveri Plastics) and the account-freeze case law (Tapas
        # D. Neogy, Neelkanth Pharma, Malabar Gold), and the per-domain
        # doctrine maps anchor the load-bearing paragraphs. Callers that
        # DO have the handoff (app.py) pass nothing and get the unchanged
        # redirect -- arrest classification is untouched either way.
        if redirect_domain in inline_domains and redirect_domain in _INLINE_DOMAIN_CONFIG:
            inline = _answer_inline_domain(question, redirect_domain)
            if inline is not None:
                return inline
        return {"state": "covered_elsewhere_in_tool", "reasoning": reasoning, "redirect_domain": redirect_domain}

    if category == "adjacent_uncovered":
        return {"state": "adjacent_uncovered", "reasoning": reasoning}

    # category == "in_scope" from here on

    # Curated statute override check -- runs BEFORE normal semantic
    # retrieval's state handling, so a known high-stakes gap (like
    # BNSS 43(5)) surfaces even if the embedding score alone wouldn't
    # clear SIMILARITY_THRESHOLD. This does NOT replace semantic
    # search -- both run, and both sets of results get combined below.
    statute_overrides = get_statute_doctrine_override(current_message)

    # ITACT Section 66A "zombie law" flag (Phase 3a, loc-transit-remand-
    # plan): struck down in 2015 but still real-world misused to file
    # FIRs, per real search. No ITACT chunk data/BNS-style structured
    # table exists yet (Phase 3b) -- this is a narrow, self-contained
    # override that fires ONLY when the person explicitly names Section
    # 66A themselves, same "known high-stakes gap" spirit as the
    # statute_doctrine_map overrides above, kept in its own module since
    # it does not go through get_statute_section (there is no valid
    # "current text" for a struck-down section to show).
    statute_overrides = statute_overrides + get_itact_status_override(current_message)

    # Explicit-section lookup: if the person literally names a section
    # ("what is section 318 of BNS", "does BNS 303 apply"), pull that
    # section's real text directly. Confirmed real gap (2026-09-01 eval):
    # "what is section 318 of BNS" scored below threshold on every
    # embedded chunk and returned no_match -- a plainly answerable
    # question producing an empty answer. Merged into statute_overrides
    # so it flows through the same combine-and-fallback logic below.
    explicit = _drop_sections_claimed_by_shelf(_explicit_section_matches(current_message), question, current_message)
    if explicit:
        seen = {(o.get("act"), o.get("section_number")) for o in statute_overrides}
        statute_overrides = statute_overrides + [
            e for e in explicit if (e["act"], e["section_number"]) not in seen
        ]

    # Offence-keyword anchor: only when the person did NOT name a section
    # themselves (explicit lookup already covers that) -- if their message
    # describes an accusation in one plain word ("stole", "cheated"),
    # anchor the matching BNS offence deterministically instead of hoping
    # the embedding ranks it first. Confirmed real gap (2026-09-01 live):
    # "arrested me... saying that i stole a goat" scored Section 303 at
    # ~0.36, behind a procedural noise match. Flows through the same
    # combine-and-fallback logic below as every other statute override.
    if not explicit:
        seen = {(o.get("act"), o.get("section_number")) for o in statute_overrides}
        statute_overrides = statute_overrides + [
            m for m in _offence_keyword_matches(current_message)
            if (m["act"], m["section_number"]) not in seen
        ]

    # General "this is probably an IT Act matter too" orientation note
    # (loc-transit-remand-plan, confirmed real gap found via live user
    # testing 2026-09-05): a cyber-crime-agency + online-post + arrest/
    # detention-shaped question (e.g. the LOC/transit-remand scenario)
    # was answering with ONLY BNSS 58/187 and never mentioning the IT Act
    # at all. Fires ONLY when no ITACT-specific match already exists
    # (an explicit "Section 66A"/numbered mention, or a keyword-anchored
    # offence like hacking) -- those are more specific and this general
    # note would only dilute them, never add to them.
    if not any((o.get("act") or "").upper() == "ITACT" for o in statute_overrides):
        from itact_section_status import get_cyber_backstory_note
        statute_overrides = statute_overrides + get_cyber_backstory_note(current_message)

    # Curated JUDGMENT anchors -- the case-law counterpart of the statute
    # doctrine overrides above. voyage-law-2 similarity is weak on long
    # narrative queries, so the genuinely-relevant judgments (civil-dispute-
    # dressed-as-cheating, grounds of arrest in writing, ...) score below
    # JUDGMENT_SIMILARITY_THRESHOLD and never reach the answer even though
    # the corpus holds them. This wires them by keyword, same as
    # statute_doctrine_map. See judgment_doctrine_map module docstring.
    from judgment_doctrine_map import get_judgment_doctrine_override
    judgment_overrides = get_judgment_doctrine_override(current_message)

    # Act shelf (act_shelf.py; ACT_SHELF=on, default off): the full text of a few Acts that are not in the library, when the Act Directory finds one of them in the question. They join the overrides:
    # a shelf Act named in the question reaches the answer regardless of what the library's own search finds. [] when the switch is off, so nothing here changes then.
    shelf_overrides = _act_shelf_matches(question, current_message)
    _progress_acts(question)
    _progress_sections(shelf_overrides)

    # everything curated that must reach the answer regardless of ranking
    overrides = statute_overrides + judgment_overrides + shelf_overrides

    # Search on the CURRENT message first, falling back to the full
    # history-included question only if that narrow search finds nothing
    # -- see _find_relevant_sections_for_turn's docstring for the
    # confirmed real failure (old conversation topics crowding out a
    # brand-new one) this fixes.
    result = _find_relevant_sections_for_turn(current_message, question)
    _progress_library(result)

    if result["state"] == "unavailable":
        # Even if retrieval is unavailable, a curated override may
        # still apply -- don't discard it just because the general
        # embedding-based path is down.
        if overrides:
            return _answer_single_match(question, overrides)
        return {"state": "retrieval_unavailable"}

    if result["state"] == "no_match":
        # A curated override can still provide an answer even when
        # normal semantic search found nothing above threshold --
        # this is the exact scenario the override exists for.
        #
        # CONFIRMED REAL FAILURE (2026-09-04): this fallback returned
        # "single_match" without 'situation_detected' at all (unlike the
        # main single_match / conflicting_matches branches below), so
        # app.py's la.get("situation") check silently defaulted to falsy
        # and the "Prepare a draft to send" button never appeared -- for
        # a real arrest situation whose only matches were statute
        # overrides (e.g. once a false-positive judgment match, like the
        # out-of-domain Rangappa fix above, correctly stops padding
        # find_relevant_sections's result out of "no_match").
        if overrides:
            return _answer_single_match(question, overrides)
        wider = _answer_from_wider_search_only(question)         # only for a question the topic bar was opened for (SCOPE_GATE=open) and only with SCI_SEARCH_MODE=feed; None otherwise
        if wider is not None:
            return wider
        return {"state": "no_match"}

    if result["state"] == "conflicting_matches":
        all_matches = result["matches"] + result.get("judgment_matches", []) + overrides
        all_matches = _inject_definitional_companions(all_matches)
        retrieved_text = format_retrieved_text_for_prompt(all_matches)
        # Same fetch-once-reuse-twice pattern as _answer_single_match's fresh path above.
        pilot_matches = _fetch_pilot_related_judgments(
            question, exclude_case_names={m.get("case_name") for m in all_matches if m.get("case_name")}, matches=all_matches
        )
        response_text = generate_grounded_response(
            question, retrieved_text, is_conflict=True, matches=all_matches, pilot_matches=pilot_matches
        )
        return {
            "state": "conflicting_matches",
            "matches": all_matches,
            "response_text": response_text,
            "situation_detected": _looks_like_situation(response_text),
            "unverified_related_judgments": pilot_matches,
        }

    # single_match -- combine statute matches with judgment matches
    # (confirmed real fix: previously judgment_matches were computed by
    # find_relevant_sections but never actually used here, so case law
    # like Arnesh Kumar never reached the response generator even when
    # it was the single highest-scoring result overall) AND any
    # curated statute overrides that matched alongside the normal
    # semantic results.
    all_matches = result["matches"] + result.get("judgment_matches", []) + overrides
    return _answer_single_match(question, all_matches)


# ---------------------------------------------------------------------------
# "Read the judgment" links (ADDED 2026-09-28).
#
# WHY: the only place an answer ever showed a link was the "Other real court cases" list, which comes from the hedged
# pilot pool and deliberately leaves out any case already used in the answer. So a case that became a verified core
# anchor (Inder Mohan Goswami, on non-bailable-warrant questions) would be NAMED in the answer while its real
# api.sci.gov.in link vanished, and core cases like Md. Ibrahim / Bhajan Lal had never shown a link at all. The user
# decided (2026-09-28): show the stored link for every judgment the answer actually relies on, for ALL core cases.
#
# Deterministic and fail-open: a case gets a link only if the answer TEXT names it; the link is the one stored on the
# case's own chunk file; a case already in the pilot list is not linked twice; any failure leaves the answer untouched.
# ---------------------------------------------------------------------------
_PARTY_SPLIT_PAT = re.compile(r"\s+vs?\.?\s+", re.IGNORECASE)
_ET_AL_TAIL_PAT = re.compile(r"(?:\s*,?\s*(?:and|&)\s+(?:anr|ors|others|another)\.?)+\s*$", re.IGNORECASE)
_GENERIC_PARTY_PAT = re.compile(r"^(?:the\s+)?(?:state|union of india|government|central bureau|cbi)\b", re.IGNORECASE)
# the last word of an institution's name is not a surname: never a reason to say an answer relies on that case (see the lone-surname fallback in _attach_cited_judgment_links)
_GENERIC_LAST_WORDS = {"authority", "authorities", "commission", "commissioner", "commissioners", "corporation", "association", "government", "department", "board", "company", "society", "council", "services",
                       "service", "limited", "bureau", "committee", "tribunal", "officer", "officers", "collector", "magistrate", "education", "institute", "university", "ministry", "panchayat",
                       "municipality", "federation", "trust", "railway", "railways", "agency", "organisation", "organization", "directorate", "administration", "secretary", "inspector",
                       "district", "court", "police", "department", "enterprises", "industries", "committee", "authority"}
_LINK_STATES = ("single_match", "conflicting_matches")


def _case_distinctive_name(case_name: str) -> str:
    """The party name an answer would use to refer to a case. The first party, minus a trailing 'and Anr.' /
    '& Ors', EXCEPT when the first party is just the State / Union of India / a Government: then the second party
    is used, so 'State of Haryana v Bhajan Lal' is 'Bhajan Lal' and can never be confused with 'Jagrup Singh v State
    of Haryana'."""
    parts = _PARTY_SPLIT_PAT.split(case_name or "", maxsplit=1)

    def clean(p):
        return _ET_AL_TAIL_PAT.sub("", p).strip(" ,.;")

    first = clean(parts[0])
    second = clean(parts[1]) if len(parts) > 1 else ""
    if _GENERIC_PARTY_PAT.match(first) and second and not _GENERIC_PARTY_PAT.match(second):
        return second
    return first


def _source_label(url: str) -> str:
    if "sci.gov.in" in url:
        return "Supreme Court of India (official)"
    if "indiankanoon.org" in url:
        return "Indian Kanoon"
    return "source link"


def _name_in_text(name: str, text: str) -> bool:
    return bool(name) and re.search(r"(?<!\w)" + re.escape(name) + r"(?!\w)", text, re.IGNORECASE) is not None


def _attach_cited_judgment_links(result):
    """Adds result['cited_judgment_links'] -- [{case_name, url, source_label}] -- for every core judgment in
    result['matches'] that the answer text names. Only for answer states; other states are returned untouched. Never
    raises (a failure returns the result as it came in)."""
    try:
        if not isinstance(result, dict) or result.get("state") not in _LINK_STATES:
            return result
        from retrieval import get_judgment_source_url

        text = result.get("response_text") or ""
        already_listed = {j.get("case_name") for j in (result.get("unverified_related_judgments") or []) if isinstance(j, dict)}
        cases = []
        for m in result.get("matches") or []:
            if isinstance(m, dict) and m.get("type") == "judgment" and m.get("case_name") and m["case_name"] not in cases:
                cases.append(m["case_name"])
        names = {c: _case_distinctive_name(c) for c in cases}
        links = []
        for case in cases:
            if case in already_listed:
                continue
            name = names[case]
            named = _name_in_text(name, text)
            if not named:
                # a lone surname is enough (the model often writes "the Goswami case") -- but only a distinctive one
                # (6+ letters, more than one word in the name, and no other retrieved case ends in the same word).
                # 2026-10-16: not an ordinary word of institutions ("Authority", "Commission", "Corporation" ...), and only as the capitalised name is written: staging showed
                # "National Legal Services Authority v Union of India" listed under a TADA answer because the answer said "an alternative, current authority".
                words = name.split()
                last = words[-1].strip(".,") if words else ""
                if (len(words) >= 2 and len(last) >= 6 and last.lower() not in _GENERIC_LAST_WORDS
                        and sum(1 for n in names.values() if n.split() and n.split()[-1].strip(".,").lower() == last.lower()) == 1):
                    named = re.search(r"(?<!\w)" + re.escape(last) + r"(?!\w)", text) is not None
            if not named:
                continue
            url = get_judgment_source_url(case)
            if not url:
                url = next((m.get("source_url") for m in result["matches"]
                            if isinstance(m, dict) and m.get("case_name") == case and isinstance(m.get("source_url"), str)
                            and m["source_url"].startswith("http")), None)
            if url:
                links.append({"case_name": case, "url": url, "source_label": _source_label(url)})
        result["cited_judgment_links"] = links
    except Exception as exc:  # fail-open: the real answer always goes out
        logger.warning("_attach_cited_judgment_links failed: %s", exc)
    return result


def _attach_register_notes(result, question=None):
    """Adds result['register_notes'] (sentences for every Overruled Register or warning-card case the answer, or the person's question, names without the answer saying it was overruled),
    result['register_possible'] (name-only matches: 'Possible match ...' and the list of decisions sharing a first party; see register_hooks.answer_notes) and result['register_not_checked'] (one fixed sentence
    naming cases on neither list). Answer states only; never raises; REGISTER_HOOKS=off skips it."""
    try:
        if not isinstance(result, dict) or result.get("state") not in _LINK_STATES:
            return result
        from register_hooks import answer_notes
        srcs = [l.get("case_name") for l in (result.get("cited_judgment_links") or []) if isinstance(l, dict)]      # the site's own listed sources need no "not checked" line
        try:                                                  # nor do the wider-search cases (SCI_SEARCH_MODE=feed): they already carry the label "(from a wider search, not independently verified)"
            import sci_search_tier
            srcs = srcs + sci_search_tier.fed_names_in(result.get("response_text") or "", extra=(result.get("unverified_related_judgments") if sci_search_tier.mode() == "feed" else None))      # in feed mode the site's pilot cases are cited like wider-search cases and carry the same label
        except Exception:  # noqa: BLE001
            pass
        try:                                                  # nor do the cases of the verbatim excerpts (ANCHORS=on): they carry "(verbatim excerpt, not yet confirmed by our reviewer)"
            import excerpt_anchors
            srcs = srcs + excerpt_anchors.names_in(result.get("response_text") or "")
        except Exception:  # noqa: BLE001
            pass
        res = answer_notes(result.get("response_text") or "", exclude_names=srcs, question=question)
        if res["notes"]:
            result["register_notes"] = res["notes"]
        if res.get("possible"):
            result["register_possible"] = res["possible"]
        if res["not_checked"]:
            result["register_not_checked"] = res["not_checked"]
        if res["review"]:
            logger.info("register: weak match(es) for review: %s", res["review"])
    except Exception as exc:  # fail-open
        logger.warning("_attach_register_notes failed: %s", exc)
    return result


# Non-answer states that still get the register's note when the person's own question names a case on the register (2026-10-16, after situation exam run 3: 5 of the 12 questions that named an
# overruled case were turned away with not a word about it, and the person may be about to rely on that case elsewhere). 'unrelated' (not a legal question) and 'budget_paused' get none.
_REFUSAL_NOTE_STATES = ("adjacent_uncovered", "covered_elsewhere_in_tool", "no_match", "classifier_unavailable", "retrieval_unavailable")


def _attach_question_register_notes(result, question=None):
    """For a result that is NOT an answer (see _REFUSAL_NOTE_STATES): adds result['register_notes'] / result['register_possible'] from the person's own question alone (a case named with a year or
    citation, by both full names, or by its first party; see register_hooks.answer_notes). There is no answer text, so no 'not checked' sentence. Never raises; REGISTER_HOOKS=off skips it."""
    try:
        if not isinstance(result, dict) or result.get("state") not in _REFUSAL_NOTE_STATES or not question:
            return result
        from register_hooks import answer_notes
        res = answer_notes("", question=question)
        if res["notes"]:
            result["register_notes"] = res["notes"]
        if res.get("possible"):
            result["register_possible"] = res["possible"]
    except Exception as exc:  # fail-open
        logger.warning("_attach_question_register_notes failed: %s", exc)
    return result


import threading

_ACTS_CACHE = threading.local()                  # per thread (a Streamlit session or a WhatsApp request): the Acts found for the question being answered, so the ACT_DETECT passes run once, not six times


def _acts_named(question):
    """The Acts of the Act Directory (act_directory.py) that the QUESTION names or clearly describes: [{'id','short','how'}], [] when none, when ACT_DIRECTORY=off, or on any failure.

    With ACT_DETECT set (act_detect.py, added 2026-10-17; off by default, so nothing changes until the owner sets it) a SECOND pass is added for a question that names no Act but plainly describes one
    ("my son ... a clerk in a government office ... taking money from a contractor"): everyday wording and the Acts' own vocabulary by regular expression, and, with ACT_DETECT=ai, one short Haiku call
    when that finds nothing. Those matches carry how='likely', so the page says "looks like it is about the X Act", exactly as a Directory phrase match already does. The result is remembered for this
    question because six places call this function and the AI pass must run at most once."""
    try:
        import act_directory
        found = act_directory.detect(question)
    except Exception:  # noqa: BLE001 -- fail-open
        return []
    try:
        import act_detect
        if not act_detect.enabled() or act_directory.mode() == "off":
            return found
        cached = getattr(_ACTS_CACHE, "value", None)
        if isinstance(cached, tuple) and cached[0] == question:
            return cached[1]
        entries = [{"id": e["id"], "short": e["short"]} for e in act_directory.load()["acts"] if e.get("detect") is not False]
        hits, rec = act_detect.more(question, found, entries)
        by_id = {e["id"]: e for e in entries}
        acts = (found + [{"id": h["id"], "short": by_id[h["id"]]["short"], "how": h["how"]} for h in hits if h["id"] in by_id])[:act_directory.MAX_ACTS]
        if rec.get("pass") not in (None, "none"):
            import hashlib
            print("ACT_DETECT " + json.dumps({"q": hashlib.sha256((question or "").encode("utf-8")).hexdigest()[:12], "named": [a["id"] for a in found], **rec}), flush=True)
        _ACTS_CACHE.value = (question, acts)
        return acts
    except Exception as exc:  # noqa: BLE001 -- fail-open
        logger.warning("act_detect pass failed: %s", type(exc).__name__)
        return found


def _payer_block(matches):
    """A prompt section for a question in which the person PAID, or was made to pay, money to a public servant (owner's staging test 2026-10-17: the answer treated a family who had paid Rs 10,000 as pure victims
    and never mentioned that giving is itself an offence under section 8 of the Prevention of Corruption Act, which exempts a person who was compelled only if he reports within seven days). It fires only when the
    Act shelf handed over section 8 because of the shelf's 'payer' pointer (act_shelf/manifest.json), so the section's own text, with its provisos, is in the material. '' otherwise. It asks the model to say what the
    section says, not to decide whether this person was compelled or has committed an offence."""
    try:
        hit = [m for m in (matches or []) if isinstance(m, dict) and m.get("source") == "act_shelf" and m.get("pointer_tag") == "payer" and str(m.get("section_number")).upper() == "8"]
        if not hit:
            return ""
        return ("\n\n## The person appears to have paid, or been made to pay, money to a public servant\n"
                "Section 8 of the Prevention of Corruption Act, 1988 is in the material above because the question describes a payment. In your OPENING paragraph or in the \"right now\" part, say plainly and in your own words, "
                "using ONLY what that section's text shows: (1) that giving an undue advantage to a public servant can itself be an offence under section 8; (2) that the section's provisos say it does not apply where a person "
                "is compelled to give it, but that the person so compelled must report the matter to the law enforcement authority or investigating agency within seven days of giving it. Do not say whether this person "
                "was compelled, and do not say that this person has or has not committed an offence: the facts are not known to you. Tell them to speak to a lawyer at once, because the seven days run from the day of the payment, "
                "and include reporting promptly as one of the things they can do. Do not suggest that they pay anything further or confront the public servant.\n")
    except Exception:  # noqa: BLE001
        return ""


def _shelf_held(matches, question):
    """Act shelf: {Directory id: {'state': 'used'|'unused', 'loaded_on'}} for the Acts the question names that have a working shelf (act_shelf.held_state); None when ACT_SHELF is off or none applies."""
    try:
        import act_shelf
        if not act_shelf.enabled():
            return None
        return act_shelf.held_state(matches, _acts_named(question)) or None
    except Exception:  # noqa: BLE001 -- fail-open
        return None


def _drop_sections_claimed_by_shelf(explicit, question, current_message):
    """Act shelf: '_explicit_section_matches' reads 'section 45 of the PMLA' as BNS section 45 (a number with no BNS/BNSS/IT Act name after it defaults to the BNS). When ACT_SHELF is on and the
    question names a shelf Act next to that number, the number is the shelf Act's: the BNS match is dropped, unless the question also puts that number next to some other name ('section 3 of POCSO and
    section 3 of the BNS'). With ACT_SHELF off, or a question that names no shelf Act, nothing is dropped."""
    try:
        if not explicit:
            return explicit
        import act_shelf
        if not act_shelf.enabled():
            return explicit
        ids = [a["id"] for a in _acts_named(question)]
        if not ids:
            return explicit
        claimed = list(act_shelf.named_sections(current_message, ids).values()) + list(act_shelf.implied_sections(current_message, ids).values())      # implied: a bare 'section 17' in a conversation about one shelf Act (SECTION_RULE)
        mine = {n for v in claimed for n in v} - act_shelf.other_numbers(current_message, ids)
        if not mine:
            return explicit
        return [e for e in explicit if not (e.get("source") == "explicit_section_ref" and str(e.get("section_number") or "").upper() in mine)]
    except Exception:  # noqa: BLE001 -- fail-open
        return explicit


def _act_shelf_matches(question, current_message):
    """Act shelf (act_shelf.py, ACT_SHELF=on, default off): when the Act Directory finds an Act with a shelf in the question, the sections of that Act that bear on it, as statute matches (source 'act_shelf') that
    join the curated overrides. [] when the switch is off, when the question names no such Act, and on any failure. One log line per question that drew a shelf Act: ACT_SHELF {...} (a hash of the question, the
    Acts, the sections and scores; never the question or the text)."""
    try:
        import act_shelf
        if not act_shelf.enabled():
            return []
        acts = _acts_named(question)
        if not acts:
            return []
        res = act_shelf.search(question, acts, current_message=current_message)
        info = res.get("info") or {}
        try:                                       # the wider search must not hand over a passage that cites the section the person named of ANOTHER statute (sci_search_tier._statute_filter)
            import sci_search_tier
            sci_search_tier.set_statute_context(act_shelf.statute_context(res.get("matches")))
        except Exception:  # noqa: BLE001
            pass
        if info.get("acts"):
            import hashlib
            print("ACT_SHELF " + json.dumps({"q": hashlib.sha256((question or "").encode("utf-8")).hexdigest()[:12], **info}), flush=True)
        return res.get("matches") or []
    except Exception as exc:  # noqa: BLE001
        logger.warning("_act_shelf_matches failed: %s", exc)
        return []


def _attach_section_note(result):
    """SECTION_RULE (default on; acts only with ACT_SHELF on): for every section of a shelf Act that the person NAMED (retrieval 'named' or 'implied'), adds result['section_note'] = [{'act','section','kind','lead',
    'texts' (the section's whole official text),...}] (section_rule.notes), shown under the answer: the explanation and the official wording side by side, always (owner, 2026-10-20). kind 'official' = the answer
    uses the number and refers to the provisos; 'not_mentioned' = it never uses the number; 'provisos' = it does not clearly set the provisos out; only the sentence above the text differs. Written by code from the
    shelf's text; judges nothing. One log line: SECTION_NOTE {...} (Act, section, kind; never the question). Never raises."""
    try:
        if not isinstance(result, dict) or result.get("state") not in ("single_match", "conflicting_matches"):
            return result
        import section_rule
        items = section_rule.notes(result.get("response_text") or "", result.get("matches"))
        if items:
            result["section_note"] = items
            print("SECTION_NOTE " + json.dumps({"sections": [f"{i['act']} s.{i['section']}: {i['kind']}" + (" +cites " + ",".join(c["section"] for c in i["cites"]) if i.get("cites") else "") for i in items]}), flush=True)
    except Exception as exc:  # noqa: BLE001 -- fail-open
        logger.warning("_attach_section_note failed: %s", type(exc).__name__)
    return result


def _attach_act_notice(result, question=None):
    """Act Directory (2026-10-16): when the person's question names (or clearly describes) an Act whose text Recourse does not hold, adds result['act_notice'] = {'kind','acts','text','html'}, one fixed notice written
    by code. kind 'opened' = the topic bar was opened for this question (the notice replaces the generic outside-scope notice, so only one shows); 'answer' = an ordinary answer that also names such an Act;
    'refusal' = a question turned away. Other states ('unrelated', 'budget_paused', errors) get nothing. Never raises; ACT_DIRECTORY=off adds nothing."""
    try:
        state = result.get("state") if isinstance(result, dict) else None
        if not question or (state not in _LINK_STATES and state not in _REFUSAL_NOTE_STATES):
            return result
        acts = _acts_named(question)
        if not acts:
            return result
        import act_directory
        if state in _LINK_STATES:
            kind = "opened" if _open_topic_info(question) else "answer"
        else:
            kind = "refusal"
        note = act_directory.notice(acts, kind, held=_shelf_held(result.get("matches"), question))
        if note:
            result["act_notice"] = note
    except Exception as exc:  # fail-open
        logger.warning("_attach_act_notice failed: %s", exc)
    return result


# ---------------------------------------------------------------------------
# SCOPE_GATE (ADDED 2026-10-16, owner's instruction: "the site should accept all topics now").  on (default: today's behaviour) | open.
#
# WHAT THE BAR WAS: classify_scope sorts a question into in_scope, covered_elsewhere_in_tool, adjacent_uncovered or unrelated. On the website cheque bounce, bank freeze, domestic violence and NDPS are
# answered inline (recourse_app passes inline_domains), so the only legal questions turned away were 'adjacent_uncovered': special laws such as TADA and the Prevention of Corruption Act, POCSO, UAPA, and civil,
# family, tax, service and company matters. 'unrelated' (not a legal question at all) is NOT part of the bar and stays refused.
#
# WHAT 'open' DOES: an 'adjacent_uncovered' question goes through the same pipeline as an in_scope one (curated overrides, library retrieval, the wider search when SCI_SEARCH_MODE=feed, the register,
# every check). Three honest additions, all written by code, none touching the Hard rules block: (1) a short scope note in the prompt telling the model not to refuse for that reason and to say plainly
# what the material does not cover (_open_topic_block); (2) when the library finds nothing and SCI_SEARCH_MODE=feed, the answer is written from the wider-search passages alone
# (_answer_from_wider_search_only; with the search off the question ends as 'no_match', as an in_scope question with no match does); (3) a fixed notice with the answer, result['outside_scope_note'].
# One log line per opened question: SCOPE_OPEN {...}. NOT measured: how good these answers are. The library has no TADA, corruption-law or civil material, so such an answer rests on the wider search alone.
# ---------------------------------------------------------------------------
OUTSIDE_SCOPE_NOTE = ("This question is about an area Recourse has not checked in depth (Recourse is built around police arrests, FIRs, criminal procedure and bail). "
                      "What follows rests only on what we could find; please confirm it with a lawyer who handles this area before you rely on it.")
_OPEN_TOPIC_BLOCK = ("\n\n## Scope note -- this question is outside the criminal-procedure library\n"
                     "The person's question is about a legal subject our library may not cover (a special law, or a civil, family, tax, service or company matter). Do not refuse it for that reason and do not say it is "
                     "outside what you can discuss. Answer it the way you answer any other question: only from the legal information given in this prompt (the rules above still apply in full, including never adding a "
                     "section number, case holding, punishment or Act name that is not in the material). Where the material does not cover a point, say so plainly in one sentence (\"I don't have information on ...\") "
                     "and say which kind of lawyer or forum handles it, instead of filling the gap from memory. "
                     "If the matter is governed by an Act or code other than the ones in the material (for example TADA, the Prevention of Corruption Act, POCSO, UAPA, or a civil, tax or company law), "
                     "do not present a BNS or BNSS section as the governing provision, the offence, the procedure or the route of appeal for it unless the material itself shows that the section applies to that matter. "
                     "A BNS or BNSS section that is only loosely related (for example a general appeal provision) is not a substitute for the statute that actually governs: say that the governing statute is not in "
                     "the material and that the forum and the route of appeal come from that statute.\n")


import threading as _threading

_OPEN_TOPIC = _threading.local()                 # per thread (a Streamlit session or a WhatsApp request): what is known about the question being answered if the topic bar was opened for it


def _scope_gate_open():
    return _env_value("SCOPE_GATE").lower() == "open"


def _open_topic_reset():
    _OPEN_TOPIC.info = None


def _open_topic_start(question, reasoning):
    _OPEN_TOPIC.info = {"question": question, "reasoning": reasoning or "", "wider_only": False}


def _open_topic_info(question):
    info = getattr(_OPEN_TOPIC, "info", None)
    return info if info and info.get("question") == question else None


_OPEN_TOPIC_EXAMPLES = "(for example TADA, the Prevention of Corruption Act, POCSO, UAPA, or a civil, tax or company law)"
_OPEN_TOPIC_NAMES = (("TADA", None), ("the Prevention of Corruption Act", "pc_act_1988"), ("POCSO", "pocso_act_2012"), ("UAPA", "uapa_1967"))


def _open_topic_block(question, matches=None):
    """The scope note for a question the topic bar would have turned away ('' for every other question, and whenever SCOPE_GATE is not 'open').  When the Act shelf put an Act's text into the material
    (matches), that Act leaves the note's list of examples of Acts that are NOT in the material; with no shelf text the note is exactly _OPEN_TOPIC_BLOCK."""
    if not (_scope_gate_open() and _open_topic_info(question)):
        return ""
    block = _OPEN_TOPIC_BLOCK
    try:
        import act_shelf
        held = set(act_shelf.shelf_ids(matches))
        if held and _OPEN_TOPIC_EXAMPLES in block:
            left = [n for n, aid in _OPEN_TOPIC_NAMES if aid not in held]
            block = block.replace(_OPEN_TOPIC_EXAMPLES, "(for example " + "".join(f"{n}, " for n in left) + "or a civil, tax or company law)")
    except Exception:  # noqa: BLE001
        pass
    return block


def _answer_from_wider_search_only(question):
    """SCOPE_GATE=open, a question the topic bar would have turned away, nothing in the library (state no_match) and SCI_SEARCH_MODE=feed: the answer is written from the wider-search passages alone
    (generate_grounded_response adds them through sci_search_tier.feed_block, which keeps its own labels and register facts). Returns an answer dict or None (search off, nothing found, generation failed
    or withheld by a check): the caller then ends as 'no_match', exactly as before. Never raises."""
    try:
        opened = bool(_scope_gate_open() and _open_topic_info(question))
        try:
            import relevance_gate
            gated = relevance_gate.emptied()                      # RELEVANCE_GATE=on removed every library match: the question stays answerable, from the wider search alone
        except Exception:  # noqa: BLE001
            gated = False
        if not (opened or gated):
            return None
        import sci_search_tier
        if sci_search_tier.mode() != "feed" or not sci_search_tier.feed_block(question):
            return None
        response_text = generate_grounded_response(question, "")
        if not response_text:
            return None
        if opened:
            _open_topic_info(question)["wider_only"] = True
        else:
            print("RELEVANCE_GATE_WIDER_ONLY " + json.dumps({"note": "every library match was below the relevance floor; answered from the wider search alone"}), flush=True)
        return {"state": "single_match", "matches": [], "response_text": response_text, "situation_detected": False, "from_cache": False, "unverified_related_judgments": []}
    except Exception as exc:  # noqa: BLE001
        logger.warning("_answer_from_wider_search_only failed: %s", exc)
        return None


def _library_summary(matches, limit=8):
    """What the library supplied for a question, for the SCOPE_OPEN log line (names and numbers only, no text): {'judgments': [{case, score, via?}], 'sections': ['BNSS 482', ...]}. The score is the
    retrieval score (a cosine similarity for a meaning hit; JUDGMENT_SIMILARITY_THRESHOLD is 0.40; 'via': 'lexical' marks a keyword backfill that ranked just below it). Never raises."""
    try:
        cases, secs = {}, []
        for m in matches or []:
            if not isinstance(m, dict):
                continue
            if m.get("type") == "judgment" and m.get("case_name"):
                sc = m.get("score")
                cur = cases.get(m["case_name"])
                if cur is None or (isinstance(sc, (int, float)) and sc > (cur[0] if isinstance(cur[0], (int, float)) else -1)):
                    cases[m["case_name"]] = (sc, m.get("retrieval"))
            elif m.get("section_number") and not m.get("case_name"):
                tag = f'{m.get("act") or "?"} {m.get("section_number")}'
                if tag not in secs:
                    secs.append(tag)
        ranked = sorted(cases.items(), key=lambda kv: -(kv[1][0] if isinstance(kv[1][0], (int, float)) else -1))
        judgments = []
        for name, (sc, via) in ranked[:limit]:
            d = {"case": name[:100], "score": round(float(sc), 3) if isinstance(sc, (int, float)) else None}
            if via:
                d["via"] = via
            judgments.append(d)
        return {"judgments": judgments, "sections": secs[:limit]}
    except Exception:  # noqa: BLE001
        return {"judgments": [], "sections": []}


def _finish_open_topic(question, result):
    """After the core has answered: marks an answer to an opened question with the fixed notice and writes the one SCOPE_OPEN log line: a hash of the question, the classifier's one-sentence reason, the
    state, whether the answer came from the wider search alone, and (added 2026-10-16, after an irrelevant library judgment was listed under a TADA answer) what the library and the wider search each supplied
    (names and scores only). Never raises."""
    try:
        info = _open_topic_info(question)
        if not info or not isinstance(result, dict):
            return result
        if result.get("state") in _LINK_STATES:
            result["outside_scope_note"] = OUTSIDE_SCOPE_NOTE
        import hashlib
        wider = []
        try:
            import sci_search_tier
            wider = [n[:100] for n in sci_search_tier.fed_case_names()][:8]
        except Exception:  # noqa: BLE001
            pass
        print("SCOPE_OPEN " + json.dumps({"q": hashlib.sha256((question or "").encode("utf-8")).hexdigest()[:12], "reasoning": info.get("reasoning", "")[:160], "state": result.get("state"),
                                          "wider_only": bool(info.get("wider_only")), "act": [a["id"] for a in _acts_named(question)], "library": _library_summary(result.get("matches")), "wider": wider}), flush=True)
    except Exception as exc:  # noqa: BLE001
        logger.warning("_finish_open_topic failed: %s", exc)
    return result


def _progress(step, **detail):
    """Live steps (progress.py). Never raises; a no-op unless a listener is set for this thread (the API service sets one; the page and the WhatsApp bot do not)."""
    try:
        import progress
        progress.emit(step, **detail)
    except Exception:  # noqa: BLE001
        pass


def _progress_on():
    try:
        import progress
        return progress.active()
    except Exception:  # noqa: BLE001
        return False


def _progress_acts(question):
    """Step 'acts': the Acts the Act Directory finds in the question. Computed only when someone is listening; _acts_named is remembered per question under ACT_DETECT, so this adds no model call."""
    if not _progress_on():
        return
    try:
        _progress("acts", names=[a.get("short") or a.get("id") for a in _acts_named(question)])
    except Exception:  # noqa: BLE001
        pass


def _progress_sections(shelf_matches):
    """Step 'sections': the shelf sections that reached the material ('PCACT s.17'), and how many of them are sections cited by the one the person asked about."""
    if not _progress_on():
        return
    try:
        ms = [m for m in (shelf_matches or []) if isinstance(m, dict) and m.get("source") == "act_shelf"]
        if not ms:
            return                                     # a step that did not happen is not reported
        _progress("sections", items=[f"{m.get('act')} s.{m.get('section_number')}" for m in ms], cited=sum(1 for m in ms if m.get("retrieval") == "cited"))
    except Exception:  # noqa: BLE001
        pass


def _progress_library(result):
    """Step 'library': how many library statute passages and judgment passages the first search found."""
    if not _progress_on():
        return
    try:
        ms = [m for m in ((result or {}).get("matches") or []) + ((result or {}).get("judgment_matches") or []) if isinstance(m, dict)]
        _progress("library", statutes=sum(1 for m in ms if m.get("type") == "statute"), judgments=sum(1 for m in ms if m.get("type") == "judgment"))
    except Exception:  # noqa: BLE001
        pass


def _progress_wider(result):
    """Step 'wider': only when the wider search contributed (SCI_SEARCH_MODE); how many wider-search judgments are listed."""
    if not _progress_on():
        return
    try:
        if isinstance(result, dict) and (result.get("sci_fed") or result.get("sci_related_judgments")):
            _progress("wider", fed=bool(result.get("sci_fed")), judgments=len(result.get("sci_related_judgments") or []))
    except Exception:  # noqa: BLE001
        pass


def answer_question(question, inline_domains=frozenset(), audience=None, channel=None):
    """Public entry point. audience ('layman' | 'lawyer') and channel ('whatsapp' | None) matter only under RESPONSE_STYLE=v3 (see answer_style.py); they are set for the length of this one call.
    The result of an answer state carries 'audience' (the voice actually used) and, for the lawyers' note, 'authorities' (the table of authorities, built by code)."""
    answer_style.set_audience(audience)
    answer_style.set_channel(channel)
    try:
        import cost_log
        cost_log.begin(question)
    except Exception:  # noqa: BLE001
        pass
    grounding_checks.reset_notes()
    _sw_start = {}
    try:                                      # the switches AS THEY WERE WHEN THE QUESTION STARTED (the question's own cost can move the budget state while it runs; the log used to show the end state)
        import cost_log
        _sw_start = {"effort": _answer_effort(), "budget": cost_log.budget_state()}
    except Exception:  # noqa: BLE001
        pass
    try:
        try:
            import cost_log
            if cost_log.budget_state() == "hard":
                print("BUDGET_PAUSED " + __import__("json").dumps({"spent_today_inr": round(cost_log.spent_today_inr(), 2), "cap_inr": cost_log.budget_cap_inr()}), flush=True)
                return {"state": "budget_paused"}
        except Exception:  # noqa: BLE001
            pass
        result = _answer_question_inner(question, inline_domains=inline_domains)
        try:
            if isinstance(result, dict) and result.get("state") in _LINK_STATES and grounding_checks.mode() in ("warn", "enforce"):
                notes = grounding_checks.pop_notes()
                if notes:
                    result["grounding_notes"] = notes
            if isinstance(result, dict) and result.get("state") in _LINK_STATES:
                _progress("checks", notes=len(result.get("grounding_notes") or []), mode=grounding_checks.mode())
        except Exception as exc:  # noqa: BLE001
            logger.warning("grounding notes failed: %s", exc)
        try:
            if isinstance(result, dict) and result.get("state") in _LINK_STATES and answer_style.is_v3():
                result["audience"] = answer_style.effective_audience()
                if result["audience"] == "lawyer":
                    result["response_text"] = _ensure_bottom_line(result.get("response_text"))
                    result["authorities"] = _build_authorities(result)
        except Exception as exc:  # fail-open: the answer always goes out
            logger.warning("authorities table failed: %s", exc)
        return result
    finally:
        try:
            import cost_log
            cost_log.finish(style=answer_style.style(), audience=answer_style.effective_audience(),
                            switches={"effort": _sw_start.get("effort", _answer_effort()), "scope_model": _scope_model(), "prompt_cache": _prompt_cache_mode(), "grounding": grounding_checks.mode(),
                                      "budget": _sw_start.get("budget", cost_log.budget_state()), "budget_after": cost_log.budget_state()})
        except Exception:  # noqa: BLE001
            pass
        answer_style.set_audience(None)
        answer_style.set_channel(None)


def _ensure_bottom_line(text):
    """The lawyers' note must open with a heading 'Bottom line'. When the model's first paragraph has no heading (staging 2026-10-14, question 6), the heading is put above it; the text is not changed otherwise."""
    try:
        t = (text or "").lstrip()
        if not t or re.match(r"[*#_ ]*bottom line\b", t, re.I):
            return text
        first = t.split("\n", 1)[0].strip()
        if re.match(r"\*\*[^*\n]{1,90}\*\*\s*$", first) or first.startswith("#"):         # the note opens with some other heading: leave it, do not guess
            return text
        return "**Bottom line**\n\n" + t
    except Exception:  # noqa: BLE001
        return text


def _build_authorities(result):
    """The lawyers' table of authorities (authorities_table.py): the library judgments the answer names and the wider-search cases it read, each with where it stands on our lists."""
    import authorities_table
    from register_hooks import case_status
    text = result.get("response_text") or ""
    named = []
    for m in result.get("matches") or []:
        if isinstance(m, dict) and m.get("type") == "judgment" and m.get("case_name") and m["case_name"] not in named:
            if _name_in_text(_case_distinctive_name(m["case_name"]), text) or any(l.get("case_name") == m["case_name"] for l in (result.get("cited_judgment_links") or []) if isinstance(l, dict)):
                named.append(m["case_name"])
    return authorities_table.build(result.get("matches"), named, result.get("cited_judgment_links"), result.get("sci_related_judgments"), case_status, anchors=result.get("anchor_excerpts"))


def _answer_question_inner(question, inline_domains=frozenset()):
    """Runs _answer_question_core (all the retrieval, generation and
    state logic; see its docstring for the possible states) and then attaches 'cited_judgment_links' -- a real,
    stored link for every judgment the answer relies on. If attaching the links ever fails, the answer is returned
    exactly as the core produced it."""
    try:
        import sci_search_tier
        sci_search_tier.reset()
        try:
            import relevance_gate
            relevance_gate.reset()
        except Exception:  # noqa: BLE001
            pass
    except Exception:  # pragma: no cover
        pass
    try:
        import excerpt_anchors
        excerpt_anchors.reset()
    except Exception:  # pragma: no cover
        pass
    _open_topic_reset()
    result = _finish_open_topic(question, _answer_question_core(question, inline_domains=inline_domains))
    try:
        result = _attach_register_notes(_attach_cited_judgment_links(result), question=question)
        result = _attach_question_register_notes(result, question=question)       # a refusal still tells the person that a case they named is on the register
        _progress("register", notes=len((result or {}).get("register_notes") or []), possible=len((result or {}).get("register_possible") or []))
        result = _attach_act_notice(result, question=question)                    # an Act the question names whose text is not in the library: one fixed notice (act_directory.py)
        result = _attach_section_note(result)                                     # a section of a shelf Act that the person named and the answer does not stand on: its official text (section_rule.py)
        try:
            import sci_search_tier
            result = sci_search_tier.attach(question, result)     # off by default (SCI_SEARCH_MODE); fail-open
            _progress_wider(result)
        except Exception:  # pragma: no cover
            pass
        try:
            import excerpt_anchors
            result = excerpt_anchors.attach(question, result)     # off by default (ANCHORS); labels the anchor cases in the answer and lists the excerpts; fail-open
        except Exception:  # pragma: no cover
            pass
        return result
    except Exception:  # pragma: no cover -- _attach already fails open; belt and braces
        return result


# ---------------------------------------------------------------------------
# ARREST_SITUATION_EXTRACTION_PROMPT
#
# EXTRACTION ONLY -- the same allowed LLM role as analyze_document() and
# interview_flow. It reports what the person SAID; run_arrest_compliance_
# checks() then decides every verdict deterministically. "unclear" is the
# honest answer whenever the conversation does not state a fact.
# ---------------------------------------------------------------------------
ARREST_SITUATION_EXTRACTION_PROMPT = """From the conversation below, extract only what the person has actually said about an arrest. Do NOT judge whether anything was lawful. Where the conversation does not state a fact, use "unclear" (for true/false fields) or null.

Return ONLY a JSON object, no other text:
{{
  "sections_cited": ["bare BNS section numbers if the person names any, e.g. \\"303\\"; [] if none"],
  "arrestee_gender": "male" | "female" | "third_gender" | "not stated",
  "arrest_datetime_full": "DD-MM-YYYY HH:MM if both date and time are given, else null",
  "production_datetime_full": "DD-MM-YYYY HH:MM if stated, else null",
  "chargesheet_filed_date": "DD-MM-YYYY if stated, else null",
  "punishment_years_upper_bound": number if the person states the maximum punishment, else null,
  "41A_or_35_BNSS_notice_issued_before_arrest": true | false | "unclear",
  "grounds_of_arrest_in_writing_furnished_to_arrestee": true | false | "unclear",
  "witness_attested_memo": true | false | "unclear",
  "family_or_friend_informed": true | false | "unclear",
  "medical_exam_at_arrest_recorded": true | false | "unclear",
  "female_officer_present_for_female_arrestee": true | false | "unclear" | "not applicable",
  "matters_raised": ["short phrases, close to the person's own words, for each grievance about the arrest or custody that is NOT one of the fields above -- e.g. 'he was slapped and kept awake all night', 'he was handcuffed to the hospital bed', 'not allowed to meet a lawyer for two days'. [] if none."]
}}

Rules:
- "false" means the person indicated it did NOT happen ("they never told him why", "no medical check-up"). "unclear" means the conversation simply does not say.
- matters_raised is for allegations the compliance checks do not cover (assault, sleep deprivation, denial of food/water, handcuffing, denial of lawyer access). Keep each phrase short and faithful to what was said.
- Do not invent dates, sections, or facts.

Conversation:
{conversation}"""


def extract_arrest_situation(conversation_text):
    """Pull the arrest-compliance fields + `matters_raised` out of a chat
    conversation, for run_arrest_compliance_checks() + the draft. Returns
    ({fields}, [matters]) or (None, []) if the model is unavailable / the
    response can't be parsed. EXTRACTION ONLY -- no verdict here."""
    if client is None or not (conversation_text or "").strip():
        return None, []
    try:
        response = client.messages.create(
            model=HAIKU_MODEL,
            max_tokens=700,
            messages=[{"role": "user", "content":
                       ARREST_SITUATION_EXTRACTION_PROMPT.format(conversation=conversation_text[:4000])}],
        )
        _note_cost("arrest_extraction", HAIKU_MODEL, response)
        raw = _extract_text_from_response(response).strip()
    except Exception:
        return None, []
    if raw.startswith("```"):
        raw = raw.strip("`")
        if raw.lower().startswith("json"):
            raw = raw[4:]
        raw = raw.strip()
    try:
        parsed = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return None, []
    if not isinstance(parsed, dict):
        return None, []

    matters = [str(m).strip() for m in (parsed.get("matters_raised") or []) if str(m).strip()]
    fields = {k: v for k, v in parsed.items() if k != "matters_raised"}
    secs = fields.get("sections_cited")
    secs = [str(s).strip() for s in secs if str(s).strip()] if isinstance(secs, list) else []

    # If the person named an offence in plain words ("theft", "cheating")
    # but no section number, anchor it deterministically -- the SAME
    # _OFFENCE_KEYWORD_ANCHORS map Lane A uses. Without a section the
    # arrest checks mostly return "Cannot Determine".
    if not secs:
        for m in _offence_keyword_matches(conversation_text):
            n = m.get("section_number")
            if n and n not in secs:
                secs.append(n)
    fields["sections_cited"] = secs
    return fields, matters